验证立项 §5.2 的「步骤模板注入 system prompt + 工具白名单 + 审批闸门」执行模型：

- ``validate_steps``：步骤数组结构校验（类型、顺序、工具名）；
- ``prompt_section``：把步骤渲染成 system prompt 段落（不注入任何外部内容，
  步骤文本来自 workflow 创建者，创建侧负责与技能正文同样的信任边界）；
- ``tool_allowlist``：所有步骤允许工具的并集，装配后过滤 ``AssembledCapabilities.tools``；
- ``force_approval``：``approval`` 步骤声明的强制审批工具集合；
- ``step_for_tool``：工具名 → 命中步骤，供 ``workflow.step`` 事件定位。

步骤 schema（spike 草案，正式实现冻结到 OpenAPI）::

    {"id": "s1", "type": "knowledge_search", "title": "检索", "instruction": "…"}
    {"id": "s2", "type": "a2a",       "title": "委派", "instruction": "…"}
    {"id": "s3", "type": "tool",      "config": {"tools": ["mcp__srv__tool"]}}
    {"id": "s4", "type": "approval",  "config": {"tools": ["send_message"]}}
    {"id": "s5", "type": "answer",    "title": "汇总回答"}

白名单语义：``knowledge_search``→``search_knowledge``；``a2a``→``send_message``；
``tool``→``config.tools`` 显式清单；``approval``/``answer`` 不提供工具。
"""

from __future__ import annotations

from typing import Any

# MVP 五类步骤（立项 §5.2）。
STEP_TYPES = ("knowledge_search", "tool", "a2a", "approval", "answer")

# 基础原生工具：白名单外一律不放行（严格白名单；模型只能从 bind_tools 的集合里选）。
TYPE_DEFAULT_TOOLS: dict[str, tuple[str, ...]] = {
    "knowledge_search": ("search_knowledge",),
    "a2a": ("send_message",),
}

MAX_STEPS = 12
MAX_INSTRUCTION_CHARS = 500
MAX_TOOL_NAME_CHARS = 200

WORKFLOW_SECTION_TEMPLATE = """<workflow name="{name}">
你正在执行预定义工作流「{name}」。请严格按以下步骤顺序推进，不要跳步、不要并步：
{steps_text}
步骤全部完成或无法继续时，才输出最终回答。步骤之外的工具调用是被禁止的。
</workflow>"""

_STEP_LINE = "{index}. [{step_type}] {title}：{instruction}"


def validate_steps(steps: Any) -> list[str]:
    """校验步骤数组；返回错误列表（空列表 = 合法）。spike 只做结构校验。"""
    errors: list[str] = []
    if not isinstance(steps, list) or not steps:
        return ["steps 必须是非空数组"]
    if len(steps) > MAX_STEPS:
        return [f"步骤数超过上限 {MAX_STEPS}"]
    seen_ids: set[str] = set()
    for index, step in enumerate(steps):
        prefix = f"steps[{index}]"
        if not isinstance(step, dict):
            errors.append(f"{prefix} 必须是对象")
            continue
        step_type = str(step.get("type") or "")
        if step_type not in STEP_TYPES:
            errors.append(f"{prefix}.type 必须是 {'/'.join(STEP_TYPES)} 之一")
        step_id = str(step.get("id") or "")
        if not step_id:
            errors.append(f"{prefix}.id 不能为空")
        elif step_id in seen_ids:
            errors.append(f"{prefix}.id 重复：{step_id}")
        else:
            seen_ids.add(step_id)
        instruction = str(step.get("instruction") or "")
        if len(instruction) > MAX_INSTRUCTION_CHARS:
            errors.append(f"{prefix}.instruction 超过 {MAX_INSTRUCTION_CHARS} 字符")
        config = step.get("config") or {}
        if config and not isinstance(config, dict):
            errors.append(f"{prefix}.config 必须是对象")
        elif step_type == "tool":
            tools = (config or {}).get("tools")
            if not isinstance(tools, list) or not tools:
                errors.append(f"{prefix}.config.tools 不能为空（tool 步骤必须显式列出工具）")
            else:
                for name in tools:
                    if not isinstance(name, str) or not name or len(name) > MAX_TOOL_NAME_CHARS:
                        errors.append(f"{prefix}.config.tools 含非法工具名")
                        break
    return errors


def _step_tools(step: dict[str, Any]) -> set[str]:
    """单个步骤允许的工具集合。"""
    step_type = str(step.get("type") or "")
    default_tools = set(TYPE_DEFAULT_TOOLS.get(step_type, ()))
    config = step.get("config") or {}
    extra = {
        str(name)
        for name in (config.get("tools") or [])
        if isinstance(name, str) and name
    }
    return default_tools | extra


def tool_allowlist(steps: list[dict[str, Any]]) -> set[str]:
    """全部步骤允许工具的并集；装配后据此过滤 tools 列表。"""
    allowed: set[str] = set()
    for step in steps:
        allowed |= _step_tools(step)
    return allowed


def force_approval(steps: list[dict[str, Any]]) -> set[str]:
    """``approval`` 步骤声明的强制审批工具集合。"""
    forced: set[str] = set()
    for step in steps:
        if str(step.get("type") or "") != "approval":
            continue
        config = step.get("config") or {}
        forced |= {
            str(name) for name in (config.get("tools") or []) if isinstance(name, str) and name
        }
    return forced


def step_for_tool(steps: list[dict[str, Any]], tool_name: str) -> dict[str, Any] | None:
    """工具名 → 命中的第一个步骤（按模板顺序）；未命中返回 None。"""
    for step in steps:
        if tool_name in _step_tools(step):
            return step
    return None


def prompt_section(name: str, steps: list[dict[str, Any]]) -> str:
    """把步骤渲染为 system prompt 末尾的 workflow 段落。"""
    lines: list[str] = []
    for index, step in enumerate(steps, start=1):
        title = str(step.get("title") or "").strip() or "（未命名）"
        instruction = str(step.get("instruction") or "").strip() or "按类型默认行为执行"
        lines.append(
            _STEP_LINE.format(
                index=index,
                step_type=str(step.get("type") or ""),
                title=title,
                instruction=instruction,
            )
        )
    return WORKFLOW_SECTION_TEMPLATE.format(name=name, steps_text="\n".join(lines))


def filter_tools(tools: list[Any], allowlist: set[str]) -> list[Any]:
    """按白名单过滤装配后的工具目录；空白名单不过滤（防御：坏模板不产生空工具集）。"""
    if not allowlist:
        return list(tools)
    return [tool for tool in tools if getattr(tool, "name", None) in allowlist]
